'use client';
import { FormEvent, useCallback, useEffect, useMemo, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import { createClient } from '@supabase/supabase-js';
import BranchPilotOwnerShell from '@/components/branchpilot-owner-shell';

const client=()=>{const u=process.env.NEXT_PUBLIC_SUPABASE_URL,k=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;return u&&k?createClient(u,k,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}):null;};
const money=(n:number)=>new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES',maximumFractionDigits:2}).format(Number(n||0));
const dateTime=(v:string)=>v?new Intl.DateTimeFormat('en-KE',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Nairobi'}).format(new Date(v)):'—';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Nairobi',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const ownerRoles=['owner','business_owner','admin'];
const roleDefaults:any={manager:{sales:true,inventory:true,finance:true,customers:true,reports:true,purchases:true,staff:false},cashier:{sales:true,inventory:true,finance:false,customers:true,reports:false,purchases:false,staff:false},stock_manager:{sales:false,inventory:true,finance:false,customers:false,reports:true,purchases:true,staff:false},accountant:{sales:true,inventory:false,finance:true,customers:true,reports:true,purchases:true,staff:false},custom:{sales:false,inventory:false,finance:false,customers:false,reports:false,purchases:false,staff:false}};
const titles:any={branches:'Branches',products:'Products',inventory:'Inventory',transfers:'Stock transfers',sales:'Sales & M-Pesa transactions',employees:'Employees',attendance:'Attendance',expenses:'Expenses',reports:'Reports',analytics:'Analytics',notifications:'Notifications', 'audit-log':'Audit log',settings:'Settings'};

export default function BranchPilotAdminSection(){
 const params=useParams(); const section=String((params as any)?.section||'sales'); const router=useRouter();
 const [db,setDb]=useState<any>(null),[user,setUser]=useState<any>(null),[biz,setBiz]=useState<any>(null),[ready,setReady]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');
 const [branches,setBranches]=useState<any[]>([]),[products,setProducts]=useState<any[]>([]),[inventory,setInventory]=useState<any[]>([]),[employees,setEmployees]=useState<any[]>([]),[sales,setSales]=useState<any[]>([]),[mpesa,setMpesa]=useState<any[]>([]),[attendance,setAttendance]=useState<any[]>([]),[expenses,setExpenses]=useState<any[]>([]),[logs,setLogs]=useState<any[]>([]),[notifications,setNotifications]=useState<any[]>([]),[saleItems,setSaleItems]=useState<any[]>([]),[stockMovements,setStockMovements]=useState<any[]>([]),[transfers,setTransfers]=useState<any[]>([]);
 const [busy,setBusy]=useState(false);
 const [branchName,setBranchName]=useState(''),[branchAddress,setBranchAddress]=useState(''),[branchPhone,setBranchPhone]=useState(''),[openingTime,setOpeningTime]=useState('08:00'),[closingTime,setClosingTime]=useState('18:00'),[latitude,setLatitude]=useState(''),[longitude,setLongitude]=useState(''),[radius,setRadius]=useState('150'),[editingBranch,setEditingBranch]=useState<string|null>(null);
 const [productName,setProductName]=useState(''),[sku,setSku]=useState(''),[barcode,setBarcode]=useState(''),[category,setCategory]=useState(''),[cost,setCost]=useState('0'),[price,setPrice]=useState('0'),[minStock,setMinStock]=useState('5'),[size,setSize]=useState(''),[color,setColor]=useState(''),[openingStock,setOpeningStock]=useState('0'),[productBranch,setProductBranch]=useState(''),[editingProduct,setEditingProduct]=useState<string|null>(null);
 const [branchFilter,setBranchFilter]=useState('all'),[employeeFilter,setEmployeeFilter]=useState('all'),[search,setSearch]=useState(''),[dateFrom,setDateFrom]=useState(today()),[dateTo,setDateTo]=useState(today());
 const [stockBranch,setStockBranch]=useState(''),[stockProduct,setStockProduct]=useState(''),[stockChange,setStockChange]=useState(''),[stockReason,setStockReason]=useState('');
 const [transferFrom,setTransferFrom]=useState(''),[transferTo,setTransferTo]=useState(''),[transferProduct,setTransferProduct]=useState(''),[transferQty,setTransferQty]=useState('1'),[transferNotes,setTransferNotes]=useState('');
 const [staffName,setStaffName]=useState(''),[staffEmail,setStaffEmail]=useState(''),[staffPhone,setStaffPhone]=useState(''),[staffPassword,setStaffPassword]=useState(''),[staffRole,setStaffRole]=useState('cashier'),[staffBranch,setStaffBranch]=useState(''),[editingEmployee,setEditingEmployee]=useState<string|null>(null);
 const [expenseCategory,setExpenseCategory]=useState('Rent'),[expenseDescription,setExpenseDescription]=useState(''),[expenseAmount,setExpenseAmount]=useState(''),[expenseMethod,setExpenseMethod]=useState('cash'),[expenseBranch,setExpenseBranch]=useState('');
 const [businessName,setBusinessName]=useState(''),[businessPhone,setBusinessPhone]=useState(''),[businessAddress,setBusinessAddress]=useState('');

 const loadData=useCallback(async(d:any,businessId:string)=>{
   const qs=await Promise.all([
    d.from('branches').select('*').eq('business_id',businessId).order('name'),
    d.from('products').select('*').eq('business_id',businessId).is('archived_at',null).order('name'),
    d.from('branch_inventory').select('id,business_id,branch_id,product_id,opening_stock,quantity,updated_at,products(id,name,sku,category,unit,cost_price,selling_price,low_stock_threshold),branches(name)').eq('business_id',businessId).order('updated_at',{ascending:false}),
    d.from('employees').select('id,user_id,branch_id,full_name,email,phone,role,is_active,scheduled_start,scheduled_end,created_at,branches(name)').eq('business_id',businessId).order('full_name'),
    d.from('sales').select('id,receipt_number,total,subtotal,discount,amount_paid,payment_status,sale_status,sold_at,branch_id,sold_by,employee_id,branches(name),employees(full_name),payments(method,amount,status)').eq('business_id',businessId).order('sold_at',{ascending:false}).limit(500),
    d.from('mpesa_transactions').select('id,transaction_code,amount,transaction_at,branch_id,employee_id,sale_id,recorded_by,branches(name),employees(full_name),sales(receipt_number)').eq('business_id',businessId).order('transaction_at',{ascending:false}).limit(1000),
    d.from('attendance').select('id,branch_id,employee_id,user_id,check_in_at,check_out_at,check_in_latitude,check_in_longitude,check_in_accuracy_m,check_out_latitude,check_out_longitude,check_out_accuracy_m,late_minutes,scheduled_start,employees(full_name,email),branches(name)').eq('business_id',businessId).order('check_in_at',{ascending:false}).limit(500),
    d.from('expenses').select('id,branch_id,category,description,amount,payment_method,reference,incurred_at,recorded_by,branches(name)').eq('business_id',businessId).order('incurred_at',{ascending:false}).limit(500),
    d.from('audit_logs').select('id,actor_user_id,action,entity_type,entity_id,details,created_at').eq('business_id',businessId).order('created_at',{ascending:false}).limit(300),
    d.from('notifications').select('id,branch_id,severity,title,message,entity_type,entity_id,is_read,created_at').eq('business_id',businessId).order('created_at',{ascending:false}).limit(300),
    d.from('sale_items').select('id,sale_id,product_id,product_name,quantity,unit_price,unit_cost,line_total,created_at').eq('business_id',businessId).order('created_at',{ascending:false}).limit(1500),
    d.from('stock_movements').select('id,branch_id,product_id,employee_id,movement_type,quantity_change,reference,notes,created_by,created_at,products(name,sku),branches(name)').eq('business_id',businessId).order('created_at',{ascending:false}).limit(500),
    d.from('stock_transfers').select('id,transfer_number,from_branch_id,to_branch_id,status,notes,created_by,received_by,created_at,received_at,stock_transfer_items(product_id,quantity,received_quantity)').eq('business_id',businessId).order('created_at',{ascending:false}).limit(300),
   ]);
   const [br,pr,iv,em,sa,mp,att,ex,lg,no,si,sm,tr]=qs;
   setBranches(br.data||[]);setProducts(pr.data||[]);setInventory(iv.data||[]);setEmployees(em.data||[]);setSales(sa.data||[]);setMpesa(mp.data||[]);setAttendance(att.data||[]);setExpenses(ex.data||[]);setLogs(lg.data||[]);setNotifications(no.data||[]);setSaleItems(si.data||[]);setStockMovements(sm.data||[]);setTransfers(tr.data||[]);
   const issue=qs.find((q:any)=>q.error);
   if(issue){setError('Some records could not be loaded: '+issue.error.message);}
   return {branches:br.data||[],products:pr.data||[]};
 },[]);
 useEffect(()=>{const d=client();if(!d){setError('Supabase is not configured.');setReady(true);return;}setDb(d);
  d.auth.getUser().then(async({data,error:authError})=>{
   if(authError||!data.user){router.replace('/owner/login');return;}setUser(data.user);
   let q=d.from('business_memberships').select('business_id,role,is_active').eq('user_id',data.user.id).eq('is_active',true).in('role',ownerRoles);
   const selected=localStorage.getItem('digibiashara_active_business_id');if(selected)q=q.eq('business_id',selected);
   const {data:m,error:me}=await q.limit(1).maybeSingle();
   if(me||!m){setError('Only an Owner account can open this management page.');setReady(true);return;}
   const {data:b,error:be}=await d.from('businesses').select('id,name,status,phone,address').eq('id',m.business_id).maybeSingle();
   if(be||!b){setError('Could not load the business profile.');setReady(true);return;}
   setBiz(b);setBusinessName(b.name||'');setBusinessPhone(b.phone||'');setBusinessAddress(b.address||'');
   localStorage.setItem('digibiashara_active_business_id',b.id);
   await loadData(d,b.id);setReady(true);
  }).catch((e:any)=>{setError(e?.message||'Could not verify your owner session.');setReady(true);});
 },[loadData,router]);

 const refresh=async()=>{if(db&&biz){setError('');await loadData(db,biz.id);}};
 const notify=(msg:string)=>{setNotice(msg);setError('');};
 const fail=(msg:string)=>{setError(msg);setNotice('');};

 async function saveBranch(e:FormEvent){e.preventDefault();if(!db||!biz||!user)return;setBusy(true);setError('');setNotice('');
  const payload:any={business_id:biz.id,name:branchName.trim(),address:branchAddress.trim()||null,phone:branchPhone.trim()||null,opening_time:openingTime||null,closing_time:closingTime||null,latitude:latitude===''?null:Number(latitude),longitude:longitude===''?null:Number(longitude),attendance_radius_m:Number(radius)||150,is_active:true};
  const r=editingBranch?await db.from('branches').update(payload).eq('business_id',biz.id).eq('id',editingBranch).select('id').single():await db.from('branches').insert(payload).select('id').single();
  if(r.error||!r.data){fail(r.error?.message||'Branch could not be saved.');setBusy(false);return;}
  if(!editingBranch){const items=products.map((p:any)=>({business_id:biz.id,branch_id:r.data.id,product_id:p.id,opening_stock:branches.length?0:Number(p.quantity||0),quantity:branches.length?0:Number(p.quantity||0)}));if(items.length){const {error:ie}=await db.from('branch_inventory').upsert(items,{onConflict:'business_id,branch_id,product_id'});if(ie){fail('Branch saved, but opening stock setup needs attention: '+ie.message);setBusy(false);await refresh();return;}}}
  notify(editingBranch?'Branch details updated.':'Branch created. Existing stock was assigned to the first branch only; additional branches start at zero until stock is received or transferred.');
  setBranchName('');setBranchAddress('');setBranchPhone('');setLatitude('');setLongitude('');setRadius('150');setEditingBranch(null);setBusy(false);await refresh();
 }
 function editBranch(b:any){setEditingBranch(b.id);setBranchName(b.name||'');setBranchAddress(b.address||'');setBranchPhone(b.phone||'');setOpeningTime(b.opening_time||'08:00');setClosingTime(b.closing_time||'18:00');setLatitude(b.latitude==null?'':String(b.latitude));setLongitude(b.longitude==null?'':String(b.longitude));setRadius(String(b.attendance_radius_m||150));window.scrollTo({top:0,behavior:'smooth'});}
 async function toggleBranch(b:any){if(!db||!biz)return;const {error:e}=await db.from('branches').update({is_active:!b.is_active}).eq('id',b.id).eq('business_id',biz.id);if(e)fail(e.message);else{notify(b.is_active?'Branch disabled. Historical transactions remain saved.':'Branch enabled.');await refresh();}}

 async function saveProduct(e:FormEvent){e.preventDefault();if(!db||!biz||!user)return;setBusy(true);setError('');setNotice('');
  if(editingProduct){
    const {error:ue}=await db.from('products').update({name:productName.trim(),sku:sku.trim()||null,barcode:barcode.trim()||null,category:category.trim()||null,cost_price:Number(cost)||0,selling_price:Number(price)||0,low_stock_threshold:Number(minStock)||0,size:size.trim()||null,color:color.trim()||null,unit:'piece',updated_at:new Date().toISOString()}).eq('id',editingProduct).eq('business_id',biz.id);
    if(ue){fail(ue.message);setBusy(false);return;}
    notify('Product details updated. Existing branch stock and historical sales were left unchanged.');
    setEditingProduct(null);setProductName('');setSku('');setBarcode('');setCategory('');setCost('0');setPrice('0');setMinStock('5');setSize('');setColor('');setBusy(false);await refresh();return;
  }
  const payload:any={business_id:biz.id,name:productName.trim(),sku:sku.trim()||null,barcode:barcode.trim()||null,category:category.trim()||null,cost_price:Number(cost)||0,selling_price:Number(price)||0,low_stock_threshold:Number(minStock)||0,size:size.trim()||null,color:color.trim()||null,unit:'piece',is_active:true,quantity:0};
  const {data:p,error:pe}=await db.from('products').insert(payload).select('id').single();if(pe||!p){fail(pe?.message||'Product could not be created.');setBusy(false);return;}
  const targets=productBranch&&productBranch!=='all'?branches.filter((b:any)=>b.id===productBranch):branches;
  if(targets.length){const targetRows=targets.map((b:any)=>({business_id:biz.id,branch_id:b.id,product_id:p.id,opening_stock:b.id===(productBranch||targets[0]?.id)?Number(openingStock)||0:0,quantity:b.id===(productBranch||targets[0]?.id)?Number(openingStock)||0:0}));
    const {error:ie}=await db.from('branch_inventory').insert(targetRows);if(ie){fail('Product created, but its branch stock was not initialized: '+ie.message);setBusy(false);await refresh();return;}
    const {error:me}=await db.from('stock_movements').insert(targetRows.filter((r:any)=>r.quantity>0).map((r:any)=>({business_id:biz.id,branch_id:r.branch_id,product_id:p.id,movement_type:'opening',quantity_change:r.quantity,reference:'OPENING-STOCK',notes:'Opening stock entered when creating product',created_by:user.id})));
    if(me){fail('Product and branch stock were saved, but the movement log failed: '+me.message);setBusy(false);await refresh();return;}
    await db.from('products').update({quantity:targetRows.reduce((sum:number,r:any)=>sum+r.quantity,0)}).eq('id',p.id).eq('business_id',biz.id);
  } else if(Number(openingStock)>0){await db.from('products').update({quantity:Number(openingStock)}).eq('id',p.id).eq('business_id',biz.id);}
  notify('Product created. Stock is stored separately by branch; no sample stock was invented.');
  setProductName('');setSku('');setBarcode('');setCategory('');setCost('0');setPrice('0');setMinStock('5');setSize('');setColor('');setOpeningStock('0');setBusy(false);await refresh();
 }
 function editProduct(p:any){setEditingProduct(p.id);setProductName(p.name||'');setSku(p.sku||'');setBarcode(p.barcode||'');setCategory(p.category||'');setCost(String(p.cost_price??0));setPrice(String(p.selling_price??0));setMinStock(String(p.low_stock_threshold??5));setSize(p.size||'');setColor(p.color||'');window.scrollTo({top:0,behavior:'smooth'});}
 async function archiveProduct(p:any){if(!db||!biz)return;if(!window.confirm('Archive '+p.name+'? Historical sales will remain available.'))return;const {error:e}=await db.from('products').update({is_active:false,archived_at:new Date().toISOString()}).eq('id',p.id).eq('business_id',biz.id);if(e)fail(e.message);else{notify('Product archived. Historical sales and movements have been retained.');await refresh();}}

 async function adjustStock(e:FormEvent){e.preventDefault();if(!db||!stockBranch||!stockProduct)return;setBusy(true);setError('');setNotice('');const {error:e1}=await db.rpc('branchpilot_adjust_stock',{p_branch_id:stockBranch,p_product_id:stockProduct,p_quantity_change:Number(stockChange),p_reason:stockReason.trim()});if(e1)fail(e1.message);else{notify('Stock adjustment saved and included in the stock movement/audit trail.');setStockChange('');setStockReason('');await refresh();}setBusy(false);}
 async function submitTransfer(e:FormEvent){e.preventDefault();if(!db||!transferFrom||!transferTo||!transferProduct)return;setBusy(true);setError('');setNotice('');const {data,error:e1}=await db.rpc('branchpilot_transfer_stock',{p_from_branch_id:transferFrom,p_to_branch_id:transferTo,p_product_id:transferProduct,p_quantity:Number(transferQty),p_notes:transferNotes.trim()||null});if(e1)fail(e1.message);else{notify('Stock transfer completed and recorded in both branches.');setTransferQty('1');setTransferNotes('');await refresh();}setBusy(false);}

 async function saveEmployee(e:FormEvent){e.preventDefault();if(!db||!biz||!staffBranch)return;setBusy(true);setError('');setNotice('');const {data:{session}}=await db.auth.getSession();if(!session){fail('Sign in again before managing staff.');setBusy(false);return;}
   const payload:any={action:editingEmployee?'update':'create',business_id:biz.id,full_name:staffName.trim(),email:staffEmail.trim().toLowerCase(),phone:staffPhone.trim(),role:staffRole,branch_id:staffBranch,permissions:roleDefaults[staffRole]||roleDefaults.custom};
   if(editingEmployee)payload.user_id=editingEmployee;else payload.password=staffPassword;
   const {data,error:e1}=await db.functions.invoke('manage-business-staff',{body:payload});
   if(e1||data?.error){fail(data?.error||e1?.message||'Employee account could not be saved.');setBusy(false);return;}
   notify(data?.message||(editingEmployee?'Employee updated.':'Employee login created and assigned to the selected branch.'));
   setEditingEmployee(null);setStaffName('');setStaffEmail('');setStaffPhone('');setStaffPassword('');setStaffRole('cashier');setStaffBranch('');setBusy(false);await refresh();
 }
 function editEmployee(emp:any){setEditingEmployee(emp.user_id);setStaffName(emp.full_name||'');setStaffEmail(emp.email||'');setStaffPhone(emp.phone||'');setStaffPassword('');setStaffRole(emp.role==='stockkeeper'?'stock_manager':emp.role||'cashier');setStaffBranch(emp.branch_id||'');window.scrollTo({top:0,behavior:'smooth'});}
 async function deactivateEmployee(emp:any){if(!db||!user||emp.user_id===user.id)return;if(!window.confirm('Disable '+emp.full_name+'? Past sales and attendance will remain.'))return;const {data,error:e1}=await db.functions.invoke('manage-business-staff',{body:{action:'deactivate',business_id:biz.id,user_id:emp.user_id}});if(e1||data?.error)fail(data?.error||e1?.message||'Could not disable employee.');else{notify('Employee access disabled. History was preserved.');await refresh();}}

 async function saveExpense(e:FormEvent){e.preventDefault();if(!db||!biz||!user)return;setBusy(true);setError('');setNotice('');const {error:e1}=await db.from('expenses').insert({business_id:biz.id,branch_id:expenseBranch||null,category:expenseCategory,description:expenseDescription.trim(),amount:Number(expenseAmount),payment_method:expenseMethod,incurred_at:new Date().toISOString(),recorded_by:user.id});if(e1)fail(e1.message);else{notify('Expense saved. It is now available in sales/expense reports.');setExpenseDescription('');setExpenseAmount('');await refresh();}setBusy(false);}
 async function saveBusiness(e:FormEvent){e.preventDefault();if(!db||!biz)return;setBusy(true);setError('');setNotice('');const {error:e1}=await db.from('businesses').update({name:businessName.trim(),phone:businessPhone.trim()||null,address:businessAddress.trim()||null}).eq('id',biz.id);if(e1)fail(e1.message);else{setBiz({...biz,name:businessName,phone:businessPhone,address:businessAddress});notify('Business profile updated. Existing categories and setup modules have not been changed.');}setBusy(false);}

 const filteredMpesa=useMemo(()=>mpesa.filter((m:any)=>{const day=String(m.transaction_at||'').slice(0,10);return (branchFilter==='all'||m.branch_id===branchFilter)&&(employeeFilter==='all'||m.employee_id===employeeFilter)&&(!search||String(m.transaction_code||'').toLowerCase().includes(search.toLowerCase())||String(m.sales?.receipt_number||'').toLowerCase().includes(search.toLowerCase()))&&(!dateFrom||day>=dateFrom)&&(!dateTo||day<=dateTo);}),[mpesa,branchFilter,employeeFilter,search,dateFrom,dateTo]);
 const filteredSales=useMemo(()=>sales.filter((s:any)=>{const day=String(s.sold_at||'').slice(0,10);return (branchFilter==='all'||s.branch_id===branchFilter)&&(employeeFilter==='all'||s.employee_id===employeeFilter||s.sold_by===employeeFilter)&&(!search||String(s.receipt_number||'').toLowerCase().includes(search.toLowerCase())||String(s.employees?.full_name||'').toLowerCase().includes(search.toLowerCase()))&&(!dateFrom||day>=dateFrom)&&(!dateTo||day<=dateTo);}),[sales,branchFilter,employeeFilter,search,dateFrom,dateTo]);
 const filteredInventory=useMemo(()=>inventory.filter((r:any)=>(stockBranch===''||r.branch_id===stockBranch)&&(!search||String(r.products?.name||'').toLowerCase().includes(search.toLowerCase())||String(r.products?.sku||'').toLowerCase().includes(search.toLowerCase()))),[inventory,stockBranch,search]);
 const filteredAttendance=useMemo(()=>attendance.filter((r:any)=>(branchFilter==='all'||r.branch_id===branchFilter)&&(employeeFilter==='all'||r.employee_id===employeeFilter)&&(!dateFrom||String(r.check_in_at).slice(0,10)>=dateFrom)&&(!dateTo||String(r.check_in_at).slice(0,10)<=dateTo)),[attendance,branchFilter,employeeFilter,dateFrom,dateTo]);
 const filteredExpenses=useMemo(()=>expenses.filter((r:any)=>(branchFilter==='all'||r.branch_id===branchFilter)&&(!dateFrom||String(r.incurred_at).slice(0,10)>=dateFrom)&&(!dateTo||String(r.incurred_at).slice(0,10)<=dateTo)),[expenses,branchFilter,dateFrom,dateTo]);

 function exportCsv(name:string,rows:any[]){if(!rows.length){fail('There are no rows to export for the selected filters.');return;}const cols=Object.keys(rows[0]);const val=(v:any)=>{const s=String(v??'');return '"'+s.replaceAll('"','""')+'"';};const csv=[cols.map(val).join(','),...rows.map(r=>cols.map(c=>val(r[c])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();URL.revokeObjectURL(url);}
 const printReport=()=>window.print();
 const selectedInventory=stockBranch?inventory.filter((r:any)=>r.branch_id===stockBranch):inventory;

 if(!ready)return <main className="bp-auth-page"><div className="bp-auth-card">Loading BranchPilot records…</div></main>;
 if(!biz)return <main className="bp-auth-page"><div className="bp-auth-card"><h1>Owner access check</h1><p className="bp-auth-message">{error||'Owner access is required.'}</p><Link href="/owner/login">Return to owner login</Link></div></main>;
 const title=titles[section]||'BranchPilot operations';
 return <BranchPilotOwnerShell title={title} subtitle="Manage the records behind your multi-branch retail operation." businessName={biz.name} email={user?.email} actions={<button className="bp-button secondary" onClick={refresh}>↻ Refresh</button>}>
 {error&&<p className="bp-alert" role="alert">{error}</p>}{notice&&<p className="bp-success" role="status">{notice}</p>}

 {section==='branches'&&<div className="bp-grid bp-two-col">
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>{editingBranch?'Edit branch':'Add a branch'}</h2><p>Configure location and attendance rules for this shop.</p></div></div>
   <form className="bp-form-grid" onSubmit={saveBranch}>
    <label>Branch name<input required value={branchName} onChange={e=>setBranchName(e.target.value)} placeholder="e.g. Nakuru branch"/></label>
    <label>Phone<input value={branchPhone} onChange={e=>setBranchPhone(e.target.value)} placeholder="+254…"/></label>
    <label>Address<input value={branchAddress} onChange={e=>setBranchAddress(e.target.value)} placeholder="Building, road, town"/></label>
    <label>Opening time<input type="time" value={openingTime} onChange={e=>setOpeningTime(e.target.value)}/></label>
    <label>Closing time<input type="time" value={closingTime} onChange={e=>setClosingTime(e.target.value)}/></label>
    <label>Attendance radius (metres)<input type="number" min="25" max="5000" value={radius} onChange={e=>setRadius(e.target.value)}/></label>
    <label>Latitude<input type="number" step="any" value={latitude} onChange={e=>setLatitude(e.target.value)} placeholder="-0.3031"/></label>
    <label>Longitude<input type="number" step="any" value={longitude} onChange={e=>setLongitude(e.target.value)} placeholder="36.0800"/></label>
    <div style={{gridColumn:'1/-1',display:'flex',gap:8,flexWrap:'wrap'}}><button className="bp-button" disabled={busy}>{busy?'Saving…':editingBranch?'Save branch changes':'Add branch'}</button>{editingBranch&&<button className="bp-button secondary" type="button" onClick={()=>{setEditingBranch(null);setBranchName('');setBranchAddress('');setBranchPhone('');}}>Cancel edit</button>}</div>
   </form>
  </section>
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>Branch directory</h2><p>{branches.filter((b:any)=>b.is_active).length} active branches · {branches.length} total</p></div></div>
   {!branches.length?<div className="bp-empty">No branches yet. Add the first shop to activate branch-based stock and attendance.</div>:<div className="bp-table-wrap"><table className="bp-table"><thead><tr><th>BRANCH</th><th>HOURS</th><th>STATUS</th><th></th></tr></thead><tbody>{branches.map((b:any)=><tr key={b.id}><td><strong>{b.name}</strong><br/><small>{b.address||'Address not set'}</small></td><td>{String(b.opening_time||'—').slice(0,5)}–{String(b.closing_time||'—').slice(0,5)}</td><td><span className={'bp-status '+(!b.is_active?'danger':'')}>{b.is_active?'Active':'Disabled'}</span></td><td><button className="bp-button secondary" onClick={()=>editBranch(b)}>Edit</button> <button className="bp-button secondary" onClick={()=>toggleBranch(b)}>{b.is_active?'Disable':'Enable'}</button></td></tr>)}</tbody></table></div>}
  </section>
 </div>}

 {section==='products'&&<div className="bp-grid bp-two-col">
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>{editingProduct?'Edit product':'Add product'}</h2><p>Prices and minimums are stored once; quantities are controlled separately for each branch.</p></div></div>
   <form className="bp-form-grid" onSubmit={saveProduct}>
    <label>Product name<input required value={productName} onChange={e=>setProductName(e.target.value)} placeholder="e.g. Classic trousers"/></label>
    <label>Category<input value={category} onChange={e=>setCategory(e.target.value)} placeholder="Clothing, shoes…"/></label>
    <label>SKU / product code<input value={sku} onChange={e=>setSku(e.target.value)}/></label><label>Barcode<input value={barcode} onChange={e=>setBarcode(e.target.value)}/></label>
    <label>Size<input value={size} onChange={e=>setSize(e.target.value)} placeholder="S, M, 32…"/></label><label>Color<input value={color} onChange={e=>setColor(e.target.value)} placeholder="Black, navy…"/></label>
    <label>Buying price (KES)<input type="number" min="0" step="0.01" required value={cost} onChange={e=>setCost(e.target.value)}/></label>
    <label>Selling price (KES)<input type="number" min="0" step="0.01" required value={price} onChange={e=>setPrice(e.target.value)}/></label>
    <label>Low-stock threshold<input type="number" min="0" step="0.001" required value={minStock} onChange={e=>setMinStock(e.target.value)}/></label>
    {!editingProduct&&<><label>Opening stock branch<select value={productBranch} onChange={e=>setProductBranch(e.target.value)}><option value="">First branch (default)</option>{branches.filter((b:any)=>b.is_active).map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label>
    <label>Opening stock quantity<input type="number" min="0" step="0.001" required value={openingStock} onChange={e=>setOpeningStock(e.target.value)}/></label></>}
    <div style={{gridColumn:'1/-1',display:'flex',gap:8,flexWrap:'wrap'}}><button className="bp-button" disabled={busy}>{busy?'Saving…':editingProduct?'Save product changes':'Save product'}</button>{editingProduct&&<button type="button" className="bp-button secondary" onClick={()=>{setEditingProduct(null);setProductName('');setSku('');setBarcode('');setCategory('');setCost('0');setPrice('0');setMinStock('5');setSize('');setColor('');}}>Cancel edit</button>}</div>
   </form>
  </section>
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>Product catalogue</h2><p>{products.length} active products</p></div><button className="bp-button secondary" onClick={()=>exportCsv('branchpilot-products',products.map((p:any)=>({name:p.name,sku:p.sku,barcode:p.barcode,category:p.category,buying_price:p.cost_price,selling_price:p.selling_price,minimum_stock:p.low_stock_threshold}))) }>Export CSV</button></div>
   <div className="bp-table-wrap"><table className="bp-table"><thead><tr><th>PRODUCT</th><th>BUY / SELL</th><th>MIN STOCK</th><th></th></tr></thead><tbody>{products.map((p:any)=><tr key={p.id}><td><strong>{p.name}</strong><br/><small>{p.category||'Uncategorised'} · {[p.size,p.color].filter(Boolean).join(' / ')}</small><br/><small>{p.sku||p.barcode||'No code'}</small></td><td>{money(p.cost_price)} / {money(p.selling_price)}</td><td>{p.low_stock_threshold}</td><td style={{display:'flex',gap:6}}><button className="bp-button secondary" onClick={()=>editProduct(p)}>Edit</button><button className="bp-button secondary" onClick={()=>archiveProduct(p)}>Archive</button></td></tr>)}</tbody></table></div>
  </section>
 </div>}

 {section==='inventory'&&<div className="bp-grid">
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>Branch inventory</h2><p>Each shop carries its own quantity. Negative stock is blocked by database rules.</p></div></div>
   <form className="bp-form-grid" onSubmit={adjustStock}>
    <label>Branch<select required value={stockBranch} onChange={e=>setStockBranch(e.target.value)}><option value="">Choose branch</option>{branches.filter((b:any)=>b.is_active).map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label>
    <label>Product<select required value={stockProduct} onChange={e=>setStockProduct(e.target.value)}><option value="">Choose product</option>{products.map((p:any)=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
    <label>Quantity change (+ add / − remove)<input type="number" step="0.001" required value={stockChange} onChange={e=>setStockChange(e.target.value)} placeholder="e.g. 10 or -1"/></label>
    <label>Reason / reference<input required value={stockReason} onChange={e=>setStockReason(e.target.value)} placeholder="Delivery note, physical count…"/></label>
    <div style={{gridColumn:'1/-1'}}><button className="bp-button" disabled={busy}>{busy?'Saving…':'Record stock adjustment'}</button></div>
   </form>
  </section>
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>Current stock by branch</h2><p>Opening stock, latest quantity and low-stock status.</p></div><button className="bp-button secondary" onClick={()=>exportCsv('branchpilot-inventory',inventory.map((r:any)=>({branch:r.branches?.name,product:r.products?.name,sku:r.products?.sku,opening_stock:r.opening_stock,current_stock:r.quantity,minimum:r.products?.low_stock_threshold,status:Number(r.quantity)<=Number(r.products?.low_stock_threshold||0)?'Low':'OK'})))}>Export CSV</button></div>
   <div className="bp-filter-row"><label>Filter branch<select className="bp-field" value={stockBranch} onChange={e=>setStockBranch(e.target.value)}><option value="">All branches</option>{branches.map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label>Search product<input className="bp-field" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Name or SKU"/></label></div>
   <div className="bp-table-wrap"><table className="bp-table"><thead><tr><th>BRANCH</th><th>PRODUCT</th><th>OPENING</th><th>CURRENT</th><th>STATUS</th></tr></thead><tbody>{filteredInventory.map((r:any)=><tr key={r.id}><td>{r.branches?.name||'—'}</td><td><strong>{r.products?.name||'Product'}</strong><br/><small>{r.products?.sku||''}</small></td><td>{r.opening_stock}</td><td>{r.quantity}</td><td><span className={'bp-status '+(Number(r.quantity)<=Number(r.products?.low_stock_threshold||0)?'warning':'')}>{Number(r.quantity)===0?'Out of stock':Number(r.quantity)<=Number(r.products?.low_stock_threshold||0)?'Low stock':'In stock'}</span></td></tr>)}</tbody></table></div>
  </section>
 </div>}

 {section==='transfers'&&<div className="bp-grid bp-two-col">
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>Transfer stock</h2><p>Move stock between two active branches. Both sides and the audit trail update together.</p></div></div>
   <form className="bp-form-grid" onSubmit={submitTransfer}>
    <label>From branch<select required value={transferFrom} onChange={e=>setTransferFrom(e.target.value)}><option value="">Select source</option>{branches.filter((b:any)=>b.is_active).map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label>
    <label>To branch<select required value={transferTo} onChange={e=>setTransferTo(e.target.value)}><option value="">Select destination</option>{branches.filter((b:any)=>b.is_active&&b.id!==transferFrom).map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label>
    <label>Product<select required value={transferProduct} onChange={e=>setTransferProduct(e.target.value)}><option value="">Select product</option>{products.map((p:any)=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
    <label>Quantity<input required type="number" min="0.001" step="0.001" value={transferQty} onChange={e=>setTransferQty(e.target.value)}/></label>
    <label style={{gridColumn:'1/-1'}}>Notes<input value={transferNotes} onChange={e=>setTransferNotes(e.target.value)} placeholder="Optional transfer notes"/></label>
    <div style={{gridColumn:'1/-1'}}><button className="bp-button" disabled={busy||!branches.filter((b:any)=>b.is_active).length||transferFrom===transferTo}>{busy?'Transferring…':'Complete stock transfer'}</button></div>
   </form>
  </section>
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>Recent stock movements</h2><p>Every stock transfer, sale and adjustment is auditable.</p></div><Link href="/admin/inventory" className="bp-button secondary">Inventory →</Link></div>
   {inventory.length===0?<div className="bp-empty">No branch inventory is available yet.</div>:<div className="bp-table-wrap"><table className="bp-table"><thead><tr><th>BRANCH</th><th>PRODUCT</th><th>CURRENT STOCK</th></tr></thead><tbody>{inventory.slice(0,12).map((r:any)=><tr key={r.id}><td>{r.branches?.name}</td><td>{r.products?.name}</td><td>{r.quantity}</td></tr>)}</tbody></table></div>}
  </section>
 </div>}

 {section==='sales'&&<div className="bp-grid">
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>M-Pesa transactions</h2><p>Transaction codes are saved permanently with the payment, sale, employee and branch.</p></div><button className="bp-button secondary" onClick={()=>exportCsv('branchpilot-mpesa-transactions',filteredMpesa.map((m:any)=>({code:m.transaction_code,amount:m.amount,receipt:m.sales?.receipt_number,employee:m.employees?.full_name,branch:m.branches?.name,date:m.transaction_at}))) }>Export CSV</button></div>
   <div className="bp-filter-row"><label>From date<input type="date" value={dateFrom} onChange={e=>setDateFrom(e.target.value)}/></label><label>To date<input type="date" value={dateTo} onChange={e=>setDateTo(e.target.value)}/></label><label>Branch<select value={branchFilter} onChange={e=>setBranchFilter(e.target.value)}><option value="all">All branches</option>{branches.map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label>Employee<select value={employeeFilter} onChange={e=>setEmployeeFilter(e.target.value)}><option value="all">All employees</option>{employees.map((e:any)=><option key={e.id} value={e.id}>{e.full_name}</option>)}</select></label><label>Search code / receipt<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="e.g. QK12…"/></label></div>
   <div className="bp-table-wrap"><table className="bp-table"><thead><tr><th>TRANSACTION CODE</th><th>AMOUNT</th><th>RECEIPT</th><th>EMPLOYEE</th><th>BRANCH</th><th>DATE / TIME</th></tr></thead><tbody>{filteredMpesa.map((m:any)=><tr key={m.id}><td><strong>{m.transaction_code}</strong></td><td>{money(m.amount)}</td><td>{m.sales?.receipt_number||'—'}</td><td>{m.employees?.full_name||'Owner / legacy payment'}</td><td>{m.branches?.name||'—'}</td><td>{dateTime(m.transaction_at)}</td></tr>)}</tbody></table>{!filteredMpesa.length&&<div className="bp-empty">No M-Pesa transactions match these filters. New BranchPilot sales will store the transaction code here.</div>}</div>
  </section>
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>Sales history</h2><p>All saved sales filtered by date, branch and employee.</p></div><button className="bp-button secondary" onClick={()=>exportCsv('branchpilot-sales',filteredSales.map((s:any)=>({receipt:s.receipt_number,total:s.total,paid:s.amount_paid,balance:Number(s.total)-Number(s.amount_paid),status:s.payment_status,employee:s.employees?.full_name,branch:s.branches?.name,date:s.sold_at}))) }>Export sales CSV</button></div>
   <div className="bp-table-wrap"><table className="bp-table"><thead><tr><th>RECEIPT</th><th>TOTAL</th><th>PAID</th><th>STATUS</th><th>EMPLOYEE</th><th>BRANCH</th><th>DATE / TIME</th></tr></thead><tbody>{filteredSales.map((s:any)=><tr key={s.id}><td><strong>{s.receipt_number}</strong></td><td>{money(s.total)}</td><td>{money(s.amount_paid)}</td><td><span className={'bp-status '+(Number(s.amount_paid)<Number(s.total)?'warning':'')}>{s.payment_status}</span></td><td>{s.employees?.full_name||'Owner / legacy sale'}</td><td>{s.branches?.name||'—'}</td><td>{dateTime(s.sold_at)}</td></tr>)}</tbody></table>{!filteredSales.length&&<div className="bp-empty">No sales match the selected filters.</div>}</div>
  </section>
 </div>}

 {section==='employees'&&<div className="bp-grid bp-two-col">
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>{editingEmployee?'Edit employee assignment':'Create employee login'}</h2><p>Only the owner can create logins, assign branches, and update staff roles.</p></div></div>
   <form className="bp-form-grid" onSubmit={saveEmployee}>
    <label>Full name<input required value={staffName} onChange={e=>setStaffName(e.target.value)}/></label><label>Email<input type="email" required value={staffEmail} onChange={e=>setStaffEmail(e.target.value)}/></label>
    <label>Phone number<input value={staffPhone} onChange={e=>setStaffPhone(e.target.value)} placeholder="+254…"/></label><label>{editingEmployee?'New password (leave blank to keep current)':'Initial password'}<input type="password" minLength={8} required={!editingEmployee} value={staffPassword} onChange={e=>setStaffPassword(e.target.value)} placeholder={editingEmployee?'Optional password reset':'At least 8 characters'}/></label>
    <label>Assigned branch<select required value={staffBranch} onChange={e=>setStaffBranch(e.target.value)}><option value="">Select branch</option>{branches.filter((b:any)=>b.is_active).map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label>
    <label>Role<select value={staffRole} onChange={e=>setStaffRole(e.target.value)}>{[['cashier','Cashier'],['manager','Manager'],['stock_manager','Stock manager'],['accountant','Accountant'],['custom','Custom permissions']].map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>
    <div style={{gridColumn:'1/-1',display:'flex',gap:8,flexWrap:'wrap'}}><button className="bp-button" disabled={busy||!branches.some((b:any)=>b.is_active)}>{busy?'Saving…':editingEmployee?'Save employee changes':'Create employee account'}</button>{editingEmployee&&<button type="button" className="bp-button secondary" onClick={()=>{setEditingEmployee(null);setStaffName('');setStaffEmail('');setStaffPhone('');setStaffPassword('');setStaffRole('cashier');setStaffBranch('');}}>Cancel edit</button>}</div>
   </form>
  </section>
  <section className="bp-panel"><div className="bp-panel-heading"><div><h2>Team directory</h2><p>{employees.filter((e:any)=>e.is_active).length} active · historical sales and attendance are retained</p></div></div>
   <div className="bp-table-wrap"><table className="bp-table"><thead><tr><th>EMPLOYEE</th><th>ROLE</th><th>BRANCH</th><th>STATUS</th><th></th></tr></thead><tbody>{employees.map((emp:any)=><tr key={emp.id}><td><strong>{emp.full_name}</strong><br/><small>{emp.email}</small></td><td>{emp.role}</td><td>{emp.branches?.name||'—'}</td><td><span className={'bp-status '+(!emp.is_active?'danger':'')}>{emp.is_active?'Active':'Disabled'}</span></td><td>{emp.is_active&&<div style={{display:'flex',gap:6}}><button className="bp-button secondary" onClick={()=>editEmployee(emp)}>Edit</button><button className="bp-button secondary" onClick={()=>deactivateEmployee(emp)}>Disable</button></div>}</td></tr>)}</tbody></table>{!employees.length&&<div className="bp-empty">No employee profiles assigned yet. Use the form to create an employee login.</div>}</div>
  </section>
 </div>}

 {section==='attendance'&&<section className="bp-panel"><div className="bp-panel-heading"><div><h2>Attendance records</h2><p>Check-in/out, late minutes, hours and recorded device location.</p></div><button className="bp-button secondary" onClick={()=>exportCsv('branchpilot-attendance',filteredAttendance.map((a:any)=>({employee:a.employees?.full_name,branch:a.branches?.name,check_in:a.check_in_at,check_out:a.check_out_at,late_minutes:a.late_minutes,hours:a.check_out_at?((new Date(a.check_out_at).getTime()-new Date(a.check_in_at).getTime())/3600000).toFixed(2):'',checkin_latitude:a.check_in_latitude,checkin_longitude:a.check_in_longitude,accuracy_m:a.check_in_accuracy_m}))) }>Export CSV</button></div>
  <div className="bp-filter-row"><label>From<input type="date" value={dateFrom} onChange={e=>setDateFrom(e.target.value)}/></label><label>To<input type="date" value={dateTo} onChange={e=>setDateTo(e.target.value)}/></label><label>Branch<select value={branchFilter} onChange={e=>setBranchFilter(e.target.value)}><option value="all">All branches</option>{branches.map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label>Employee<select value={employeeFilter} onChange={e=>setEmployeeFilter(e.target.value)}><option value="all">All employees</option>{employees.map((e:any)=><option key={e.id} value={e.id}>{e.full_name}</option>)}</select></label></div>
  <div className="bp-table-wrap"><table className="bp-table"><thead><tr><th>EMPLOYEE</th><th>BRANCH</th><th>CHECK IN</th><th>CHECK OUT</th><th>LATE</th><th>HOURS</th><th>LOCATION / ACCURACY</th></tr></thead><tbody>{filteredAttendance.map((a:any)=>{const hours=a.check_out_at?(new Date(a.check_out_at).getTime()-new Date(a.check_in_at).getTime())/3600000:null;return <tr key={a.id}><td><strong>{a.employees?.full_name||'Employee'}</strong></td><td>{a.branches?.name||'—'}</td><td>{dateTime(a.check_in_at)}</td><td>{dateTime(a.check_out_at)}</td><td><span className={'bp-status '+(a.late_minutes>0?'warning':'')}>{a.late_minutes||0} min</span></td><td>{hours==null?'Shift open':hours.toFixed(2)}</td><td>{a.check_in_latitude==null?'Not shared':a.check_in_latitude.toFixed(5)+', '+a.check_in_longitude?.toFixed(5)+' · '+(a.check_in_accuracy_m?Math.round(a.check_in_accuracy_m)+'m':'accuracy n/a')}</td></tr>})}</tbody></table>{!filteredAttendance.length&&<div className="bp-empty">No attendance records found for these filters.</div>}</div>
 </section>}

 {section==='expenses'&&<div className="bp-grid bp-two-col"><section className="bp-panel"><div className="bp-panel-heading"><div><h2>Record an expense</h2><p>Rent, electricity, transport, salaries, marketing, repairs and other costs.</p></div></div>
  <form className="bp-form-grid" onSubmit={saveExpense}><label>Category<select value={expenseCategory} onChange={e=>setExpenseCategory(e.target.value)}>{['Rent','Electricity','Transport','Salaries','Marketing','Repairs','Supplies','Utilities','Other'].map(x=><option key={x}>{x}</option>)}</select></label><label>Amount (KES)<input type="number" required min="0.01" step="0.01" value={expenseAmount} onChange={e=>setExpenseAmount(e.target.value)}/></label><label>Branch<select value={expenseBranch} onChange={e=>setExpenseBranch(e.target.value)}><option value="">Business-wide</option>{branches.map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label>Payment method<select value={expenseMethod} onChange={e=>setExpenseMethod(e.target.value)}>{['cash','mpesa','bank','card','other'].map(x=><option key={x}>{x}</option>)}</select></label><label style={{gridColumn:'1/-1'}}>Description<input required value={expenseDescription} onChange={e=>setExpenseDescription(e.target.value)} placeholder="What was the money spent on?"/></label><div style={{gridColumn:'1/-1'}}><button className="bp-button" disabled={busy}>{busy?'Saving…':'Save expense'}</button></div></form>
 </section><section className="bp-panel"><div className="bp-panel-heading"><div><h2>Expenses ledger</h2><p>Saved expenses, branch and payment method.</p></div><button className="bp-button secondary" onClick={()=>exportCsv('branchpilot-expenses',filteredExpenses.map((x:any)=>({date:x.incurred_at,branch:x.branches?.name,category:x.category,description:x.description,amount:x.amount,payment_method:x.payment_method,reference:x.reference}))) }>Export CSV</button></div>
 <div className="bp-filter-row"><label>From<input type="date" value={dateFrom} onChange={e=>setDateFrom(e.target.value)}/></label><label>To<input type="date" value={dateTo} onChange={e=>setDateTo(e.target.value)}/></label><label>Branch<select value={branchFilter} onChange={e=>setBranchFilter(e.target.value)}><option value="all">All branches</option>{branches.map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label></div>
 <table className="bp-table"><thead><tr><th>DATE</th><th>CATEGORY</th><th>DESCRIPTION</th><th>AMOUNT</th><th>METHOD</th></tr></thead><tbody>{filteredExpenses.map((x:any)=><tr key={x.id}><td>{dateTime(x.incurred_at)}</td><td>{x.category}</td><td><strong>{x.description}</strong><br/><small>{x.branches?.name||'Business-wide'}</small></td><td>{money(x.amount)}</td><td>{x.payment_method}</td></tr>)}</tbody></table></section></div>}

 {section==='reports'&&<section className="bp-panel"><div className="bp-panel-heading"><div><h2>Business reports</h2><p>Filter sales and costs, then export CSV or print/save this report as PDF.</p></div><div style={{display:'flex',gap:8,flexWrap:'wrap'}}><button className="bp-button secondary" onClick={()=>exportCsv('branchpilot-sales-report',filteredSales.map((s:any)=>({date:s.sold_at,receipt:s.receipt_number,branch:s.branches?.name,employee:s.employees?.full_name,revenue:s.total,amount_paid:s.amount_paid,balance:Number(s.total)-Number(s.amount_paid),status:s.payment_status})))}>Sales CSV</button><button className="bp-button secondary" onClick={()=>exportCsv('branchpilot-expense-report',filteredExpenses.map((x:any)=>({date:x.incurred_at,branch:x.branches?.name,category:x.category,description:x.description,amount:x.amount,method:x.payment_method})))}>Expenses CSV</button><button className="bp-button" onClick={printReport}>Print / Save PDF</button></div></div>
  <div className="bp-filter-row"><label>From<input type="date" value={dateFrom} onChange={e=>setDateFrom(e.target.value)}/></label><label>To<input type="date" value={dateTo} onChange={e=>setDateTo(e.target.value)}/></label><label>Branch<select value={branchFilter} onChange={e=>setBranchFilter(e.target.value)}><option value="all">All branches</option>{branches.map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label>Employee<select value={employeeFilter} onChange={e=>setEmployeeFilter(e.target.value)}><option value="all">All employees</option>{employees.map((e:any)=><option key={e.id} value={e.id}>{e.full_name}</option>)}</select></label></div>
  <div className="bp-grid bp-kpi-grid"><div className="bp-panel"><div className="bp-kpi-label">Revenue</div><div className="bp-kpi-value">{money(filteredSales.reduce((a:number,s:any)=>a+Number(s.total||0),0))}</div></div><div className="bp-panel"><div className="bp-kpi-label">Collections</div><div className="bp-kpi-value">{money(filteredSales.reduce((a:number,s:any)=>a+Number(s.amount_paid||0),0))}</div></div><div className="bp-panel"><div className="bp-kpi-label">Expenses</div><div className="bp-kpi-value">{money(filteredExpenses.reduce((a:number,x:any)=>a+Number(x.amount||0),0))}</div></div><div className="bp-panel"><div className="bp-kpi-label">Estimated profit</div><div className="bp-kpi-value">{money(filteredSales.reduce((a:number,s:any)=>a+Number(s.total||0),0)-filteredExpenses.reduce((a:number,x:any)=>a+Number(x.amount||0),0)-saleItems.filter((i:any)=>filteredSales.some((s:any)=>s.id===i.sale_id)).reduce((a:number,i:any)=>a+Number(i.unit_cost||0)*Number(i.quantity||0),0))}</div><div className="bp-kpi-sub">Revenue − cost of goods sold − expenses; excludes unrecorded costs.</div></div></div>
  <div className="bp-table-wrap"><table className="bp-table"><thead><tr><th>DATE</th><th>RECEIPT</th><th>BRANCH</th><th>EMPLOYEE</th><th>REVENUE</th><th>COLLECTED</th><th>BALANCE</th></tr></thead><tbody>{filteredSales.map((s:any)=><tr key={s.id}><td>{dateTime(s.sold_at)}</td><td>{s.receipt_number}</td><td>{s.branches?.name||'—'}</td><td>{s.employees?.full_name||'—'}</td><td>{money(s.total)}</td><td>{money(s.amount_paid)}</td><td>{money(Number(s.total)-Number(s.amount_paid))}</td></tr>)}</tbody></table></div>
 </section>}

 {section==='analytics'&&<div className="bp-grid bp-two-col"><section className="bp-panel"><div className="bp-panel-heading"><div><h2>Branch performance</h2><p>Ranked by recorded sales across the selected period of loaded history.</p></div></div>
  {branches.length===0?<div className="bp-empty">Add branches to compare performance.</div>:<div className="bp-bar-list">{branches.map((b:any)=>{const total=sales.filter((s:any)=>s.branch_id===b.id&&(!dateFrom||String(s.sold_at).slice(0,10)>=dateFrom)&&(!dateTo||String(s.sold_at).slice(0,10)<=dateTo)).reduce((n:number,s:any)=>n+Number(s.total||0),0);const max=Math.max(...branches.map((x:any)=>sales.filter((s:any)=>s.branch_id===x.id&&(!dateFrom||String(s.sold_at).slice(0,10)>=dateFrom)&&(!dateTo||String(s.sold_at).slice(0,10)<=dateTo)).reduce((n:number,s:any)=>n+Number(s.total||0),0)),1);return <div className="bp-bar-item" key={b.id}><span>{b.name}</span><div className="bp-bar-track"><span style={{width:(total/max*100)+'%'}}/></div><strong>{money(total)}</strong></div>})}</div>}
 </section><section className="bp-panel"><div className="bp-panel-heading"><div><h2>Product performance</h2><p>Best sellers from recorded item lines</p></div></div>
  {(()=>{const map=new Map<string,number>();for(const it of saleItems){const s=sales.find((x:any)=>x.id===it.sale_id);if(!s)continue;const d=String(s.sold_at).slice(0,10);if((dateFrom&&d<dateFrom)||(dateTo&&d>dateTo))continue;map.set(it.product_name,(map.get(it.product_name)||0)+Number(it.quantity||0));}const rows=[...map.entries()].map(([name,qty])=>({name,qty})).sort((a,b)=>b.qty-a.qty).slice(0,12);return rows.length?<table className="bp-table"><thead><tr><th>PRODUCT</th><th>UNITS</th></tr></thead><tbody>{rows.map(r=><tr key={r.name}><td><strong>{r.name}</strong></td><td>{r.qty}</td></tr>)}</tbody></table>:<div className="bp-empty">No product sales were recorded for this period.</div>})()}
 </section><section className="bp-panel"><div className="bp-panel-heading"><div><h2>Cash vs M-Pesa</h2><p>Amounts from recorded payments for the date range.</p></div></div>
  {(()=>{const selected=sales.filter((s:any)=>{const day=String(s.sold_at).slice(0,10);return (!dateFrom||day>=dateFrom)&&(!dateTo||day<=dateTo)});const ids=selected.map((s:any)=>s.id);const payments=selected.flatMap((s:any)=>Array.isArray(s.payments)?s.payments:[]);const cash=payments.filter((p:any)=>p.method==='cash'&&p.status==='recorded').reduce((n:number,p:any)=>n+Number(p.amount||0),0);const mp=payments.filter((p:any)=>p.method==='mpesa'&&p.status==='recorded').reduce((n:number,p:any)=>n+Number(p.amount||0),0);const total=Math.max(cash,mp,1);return <><div className="bp-bar-item"><span>Cash</span><div className="bp-bar-track"><span style={{width:cash/total*100+'%'}}/></div><strong>{money(cash)}</strong></div><div className="bp-bar-item" style={{marginTop:18}}><span>M-Pesa</span><div className="bp-bar-track"><span style={{width:mp/total*100+'%'}}/></div><strong>{money(mp)}</strong></div><p className="bp-map-note" style={{marginTop:16}}>Payments are joined from the saved sales history. Historical sales without payment rows are not imputed.</p></>})()}
 </section></div>}

 {section==='notifications'&&<section className="bp-panel"><div className="bp-panel-heading"><div><h2>Business alerts</h2><p>Saved operational events and live low-stock conditions.</p></div><span className="bp-pill">{notifications.filter((n:any)=>!n.is_read).length} unread</span></div>
  <div className="bp-table-wrap"><table className="bp-table"><thead><tr><th>TIME</th><th>ALERT</th><th>BRANCH</th><th>STATUS</th></tr></thead><tbody>
   {inventory.filter((r:any)=>Number(r.quantity)<=Number(r.products?.low_stock_threshold||0)).map((r:any)=><tr key={'low-'+r.id}><td>{dateTime(r.updated_at)}</td><td><strong>{Number(r.quantity)===0?'Out of stock':'Low stock'}: {r.products?.name}</strong><br/><small>Current {r.quantity}; threshold {r.products?.low_stock_threshold}</small></td><td>{r.branches?.name}</td><td><span className="bp-status warning">Needs attention</span></td></tr>)}
   {notifications.map((n:any)=><tr key={n.id}><td>{dateTime(n.created_at)}</td><td><strong>{n.title}</strong><br/><small>{n.message}</small></td><td>{branches.find((b:any)=>b.id===n.branch_id)?.name||'Business-wide'}</td><td><span className={'bp-status '+(n.severity==='critical'?'danger':n.severity==='warning'?'warning':'')}>{n.is_read?'Read':n.severity||'Info'}</span></td></tr>)}
  </tbody></table>{!notifications.length&&!inventory.some((r:any)=>Number(r.quantity)<=Number(r.products?.low_stock_threshold||0))&&<div className="bp-empty">No alerts yet. Alerts will appear as real stock and attendance activity is recorded.</div>}</div>
 </section>}

 {section==='audit-log'&&<section className="bp-panel"><div className="bp-panel-heading"><div><h2>Audit log</h2><p>Recent recorded changes, sales, stock movements and staff events.</p></div><button className="bp-button secondary" onClick={()=>exportCsv('branchpilot-audit-log',logs.map((l:any)=>({time:l.created_at,actor:l.actor_user_id,action:l.action,entity:l.entity_type,entity_id:l.entity_id,details:JSON.stringify(l.details||{})})))}>Export CSV</button></div>
  <div className="bp-table-wrap"><table className="bp-table"><thead><tr><th>DATE / TIME</th><th>ACTION</th><th>ENTITY</th><th>DETAILS</th><th>ACTOR</th></tr></thead><tbody>{logs.map((l:any)=><tr key={l.id}><td>{dateTime(l.created_at)}</td><td><strong>{l.action}</strong></td><td>{l.entity_type}</td><td style={{whiteSpace:'normal',minWidth:220}}>{JSON.stringify(l.details||{})}</td><td>{String(l.actor_user_id||'—').slice(0,8)}</td></tr>)}</tbody></table>{!logs.length&&<div className="bp-empty">No audit events recorded yet.</div>}</div>
 </section>}

 {section==='settings'&&<div className="bp-grid bp-two-col"><section className="bp-panel"><div className="bp-panel-heading"><div><h2>Business profile</h2><p>Update your business contact details. Categories and business features stay in the existing setup flow.</p></div></div>
  <form className="bp-form-grid" onSubmit={saveBusiness}><label>Business name<input required value={businessName} onChange={e=>setBusinessName(e.target.value)}/></label><label>Phone<input value={businessPhone} onChange={e=>setBusinessPhone(e.target.value)}/></label><label style={{gridColumn:'1/-1'}}>Address<input value={businessAddress} onChange={e=>setBusinessAddress(e.target.value)}/></label><div style={{gridColumn:'1/-1'}}><button className="bp-button" disabled={busy}>{busy?'Saving…':'Save business profile'}</button></div></form>
 </section><section className="bp-panel"><div className="bp-panel-heading"><div><h2>BranchPilot settings</h2><p>Working hours, branch GPS radius and inventory are configured per branch.</p></div></div><div className="bp-grid"><Link className="bp-action-tile" href="/admin/branches"><span className="tile-icon">⌖</span><span><b>Branch and attendance settings</b><small>Configure opening hours, GPS coordinates and attendance radius.</small></span></Link><Link className="bp-action-tile" href="/admin/inventory"><span className="tile-icon">▦</span><span><b>Stock settings</b><small>Set opening stock, minimum levels, and authorized adjustments.</small></span></Link><Link className="bp-action-tile" href="/businesses"><span className="tile-icon">▣</span><span><b>Business categories and modules</b><small>Existing DigiBiashara business setup and category selection remains unchanged.</small></span></Link></div></section></div>}

 {!Object.keys(titles).includes(section)&&<section className="bp-panel"><h2>Choose an operations page</h2><p className="bp-map-note">Use the BranchPilot navigation to open a supported management section.</p></section>}
 </BranchPilotOwnerShell>;
}
